<script setup lang="ts">
// THROWAWAY — selected visual A, one route with ?page= and ?theme=. In-memory demo only.
import {ref,computed,onMounted,onUnmounted,watch,nextTick} from 'vue';
import {ChatbubbleEllipsesOutline,BookOutline,GridOutline,GitNetworkOutline,SettingsOutline,PersonCircleOutline,ChevronDownOutline,AddOutline,PaperPlaneOutline,AttachOutline,CloseOutline,SearchOutline,ChevronForwardOutline,MenuOutline,SunnyOutline,MoonOutline,ArrowBackOutline,DocumentTextOutline,CheckmarkCircleOutline,AlertCircleOutline,PlayOutline,SaveOutline,FolderOpenOutline,OptionsOutline,CopyOutline} from '@vicons/ionicons5';
const isDev = import.meta.env.DEV;
const params=new URLSearchParams(location.search);
const pages=['chat','knowledge','agents','workflows','settings'];
const page=ref(pages.includes(params.get('page')||'')?params.get('page')!:'chat');
const narrow=ref(window.innerWidth<=760);
function resize(){narrow.value=window.innerWidth<=760}
const dark=ref(params.get('theme')==='dark'),mobile=ref(false),collapsed=ref(false),account=ref(false),assistantMenu=ref(false),drawer=ref(''),toast=ref('');
const assistant=ref('知识助手'),question=ref(''),conversation=ref(false),loading=ref(false),sessionTitle=ref('新对话'),notice=ref(true),attached=ref('');
const messages=ref<{role:string,text:string}[]>([]);
const histories=ref(['公司差旅报销政策解读','如何优化产品需求文档结构','年终总结内容框架建议','竞争对手分析要点梳理','项目风险管理常见问题']);
const nav=[{key:'chat',label:'对话',icon:ChatbubbleEllipsesOutline},{key:'knowledge',label:'知识库',icon:BookOutline},{key:'agents',label:'智能体',icon:GridOutline},{key:'workflows',label:'工作流',icon:GitNetworkOutline}];
const query=ref(''),detail=ref(false),editor=ref(false),activeNode=ref('知识检索'),running=ref(false),setting=ref('模型配置');
const libraries=ref([{name:'企业制度',desc:'让日常问题，有据可查',count:12},{name:'产品资料',desc:'产品说明、需求与使用指南',count:8},{name:'研究笔记',desc:'把零散发现整理成可用知识',count:5}]);
const library=ref('企业制度');
const docs=ref([{name:'差旅管理办法.pdf',size:'1.2 MB',status:'可检索'},{name:'员工入职指南.pdf',size:'860 KB',status:'可检索'},{name:'费用报销流程.docx',size:'240 KB',status:'处理失败'},{name:'团队协作规范.md',size:'18 KB',status:'处理中'}]);
const filteredDocs=computed(()=>docs.value.filter(d=>d.name.includes(query.value)));
const agents=ref([{name:'知识助手',desc:'基于企业资料回答问题',kb:'企业制度'},{name:'产品顾问',desc:'解释产品能力与使用方法',kb:'产品资料'}]);
const modal=ref(''),formName=ref(''),formDesc=ref(''),selectedKnowledge=ref('企业制度');
const settings=['模型配置','解析引擎','MCP 服务','意图路由','样例查询','知识图谱','外观'];
let timers:ReturnType<typeof setTimeout>[]=[];
function later(fn:()=>void,ms=900){timers.push(setTimeout(fn,ms))}
function notify(t:string){toast.value=t;later(()=>toast.value='',2500)}
function sync(){const q=new URLSearchParams(location.search);q.set('variant','A');q.set('page',page.value);q.set('theme',dark.value?'dark':'light');history.replaceState({},'',location.pathname+'?'+q)}
function go(p:string){page.value=p;detail.value=false;editor.value=false;query.value='';mobile.value=false;drawer.value='';sync()}
function theme(){dark.value=!dark.value;sync()}
function newChat(){go('chat');conversation.value=false;messages.value=[];sessionTitle.value='新对话';question.value='';attached.value=''}
function openChat(t:string){go('chat');sessionTitle.value=t;conversation.value=true;messages.value=[{role:'user',text:'出差前需要准备哪些材料？'},{role:'assistant',text:'根据《差旅管理办法》，建议先准备以下材料：\n\n1. 事前申请：说明出差事由、目的地、时间与人员。\n2. 行程预算：列明交通、住宿和其他预计费用。\n3. 审批记录：保留审批结果，便于后续报销。\n\n提交前，可再核对相关部门的具体要求。'}]}
function send(){if(!question.value.trim()||loading.value)return;const text=question.value.trim();if(!conversation.value){sessionTitle.value=text.slice(0,20);histories.value.unshift(sessionTitle.value)}conversation.value=true;messages.value.push({role:'user',text});question.value='';loading.value=true;later(()=>{messages.value.push({role:'assistant',text:'这是一条演示回答。\n\n我从所选知识库中找到了相关说明。你可以点击下方引用查看原文，或继续提问。\n\n正式版本将沿用项目现有的检索、流式回答和智能体能力。'});loading.value=false})}
function upload(e:Event){const f=(e.target as HTMLInputElement).files?.[0];if(!f)return;if(page.value==='chat'){attached.value=f.name;notify('已添加演示附件，文件未上传')}else{docs.value.unshift({name:f.name,size:Math.round(f.size/1024)+' KB',status:'处理中'});notify('演示文件已加入列表');later(()=>docs.value[0].status='可检索',1800)}}
function retry(d:any){d.status='处理中';later(()=>{d.status='可检索';notify('演示处理完成')},1200)}
function startModal(type:string){modal.value=type;formName.value='';formDesc.value=''}
function saveModal(){if(!formName.value.trim())return;if(modal.value==='knowledge')libraries.value.push({name:formName.value,desc:formDesc.value||'新的知识资料集合',count:0});else if(modal.value==='agent')agents.value.push({name:formName.value,desc:formDesc.value||'新的知识助手',kb:selectedKnowledge.value});modal.value='';notify('已保存到本次演示')}
function run(){running.value=true;later(()=>{running.value=false;drawer.value='run';notify('演示流程运行完成')},1200)}
watch([drawer,modal,mobile],async()=>{await nextTick();const panel=document.querySelector('.modal,.drawer') || (mobile.value?document.querySelector('.sidebar.open'):null);(panel?.querySelector('input,button,select,textarea') as HTMLElement)?.focus()});
function key(e:KeyboardEvent){if(e.key==='Tab'){const panel=document.querySelector('.modal,.drawer') || (mobile.value?document.querySelector('.sidebar.open'):null);if(panel){const items=Array.from(panel.querySelectorAll('button,input,select,textarea,a[href]')).filter((n:any)=>!n.disabled&&n.offsetParent!==null) as HTMLElement[];const first=items[0],last=items[items.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}}if(e.key==='Escape'){drawer.value='';modal.value='';mobile.value=false;assistantMenu.value=false;account.value=false}}
onMounted(()=>{window.addEventListener('keydown',key);window.addEventListener('resize',resize);sync()});onUnmounted(()=>{timers.forEach(clearTimeout);window.removeEventListener('keydown',key);window.removeEventListener('resize',resize)});
</script>
<template>
<div class="app" :class="{dark,collapsed}">
  <div v-if="mobile" class="shade mobile-shade" @click="mobile=false"></div>
  <aside class="sidebar" :class="{open:mobile}" :inert="(narrow&&!mobile)||!!drawer||!!modal">
    <div class="brand"><img src="/notellm-prototype/logo.png" alt=""><strong>NoteLLM</strong><button class="icon collapse" aria-label="收起导航" @click="collapsed=!collapsed"><MenuOutline/></button><button class="icon mobile-close" aria-label="关闭导航" @click="mobile=false"><CloseOutline/></button></div>
    <button class="primary new-chat" @click="newChat"><AddOutline/><span>新建对话</span></button>
    <nav><button v-for="n in nav" :key="n.key" :class="{active:page===n.key}" :title="n.label" @click="go(n.key)"><component :is="n.icon"/><span>{{n.label}}</span></button></nav>
    <section class="history"><h3>最近对话</h3><button v-for="(h,i) in histories.slice(0,5)" :key="i" @click="openChat(h)"><ChatbubbleEllipsesOutline/><span>{{h}}</span></button><button @click="drawer='history'"><ChatbubbleEllipsesOutline/><span>查看全部对话</span><ChevronForwardOutline/></button></section>
    <div class="side-bottom"><button :class="{active:page==='settings'}" @click="go('settings')"><SettingsOutline/><span>设置</span></button><button @click="account=!account"><PersonCircleOutline/><span>个人账号</span><ChevronDownOutline/></button><div v-if="account" class="account-menu"><b>演示账号</b><small>所有操作仅保留在本次预览</small><button @click="theme">{{dark?'切换浅色':'切换深色'}}主题</button><button @click="drawer='help';account=false">帮助与说明</button></div></div>
  </aside>
  <div class="mobile-head"><button class="icon" aria-label="打开导航" @click="mobile=true"><MenuOutline/></button><b>NoteLLM</b><button class="icon" aria-label="切换主题" @click="theme"><component :is="dark?SunnyOutline:MoonOutline"/></button></div>
  <main class="surface" :inert="!!drawer||!!modal||mobile">
    <template v-if="page==='chat'">
      <header class="chat-header"><div class="assistant-picker"><button @click="assistantMenu=!assistantMenu">{{assistant}}<ChevronDownOutline/></button><div v-if="assistantMenu" class="popover"><button v-for="a in agents" @click="assistant=a.name;assistantMenu=false">{{a.name}}</button></div></div><div v-if="conversation" class="chat-actions"><span>{{sessionTitle}}</span><button class="icon" aria-label="对话设置" @click="drawer='chat-settings'"><OptionsOutline/></button></div></header>
      <div v-if="!conversation" class="empty-chat"><h1>今天，想了解什么？</h1><p>从你的知识中寻找答案</p><form class="composer" @submit.prevent="send"><span v-if="attached" class="attachment">{{attached}}<button type="button" aria-label="移除附件" @click="attached=''"><CloseOutline/></button></span><textarea v-model="question" aria-label="输入问题" placeholder="提问或输入你的问题…" @keydown.enter.exact.prevent="send"></textarea><div class="composer-bottom"><label class="icon" title="添加附件"><AttachOutline/><input type="file" aria-label="添加附件" @change="upload"></label><button class="send" aria-label="发送问题" :disabled="!question.trim()" type="submit"><PaperPlaneOutline/></button></div></form><div class="quick-actions"><button @click="go('knowledge')"><BookOutline/>浏览知识库</button><i></i><button @click="assistantMenu=true"><GridOutline/>选择智能体</button></div></div>
      <div v-else class="conversation"><div class="messages"><article v-for="(m,i) in messages" :key="i" :class="m.role"><div v-if="m.role==='assistant'" class="answer-avatar"><img src="/notellm-prototype/logo.png" alt="NoteLLM"></div><div><p>{{m.text}}</p><button v-if="m.role==='assistant'" class="citation" @click="drawer='source'"><DocumentTextOutline/>差旅管理办法.pdf · 第 3 页<ChevronForwardOutline/></button></div></article><div v-if="loading" role="status" class="generating">正在查找资料…</div></div><form class="composer conversation-composer" @submit.prevent="send"><span v-if="attached" class="attachment">{{attached}}</span><textarea v-model="question" aria-label="继续提问" placeholder="继续提问…" @keydown.enter.exact.prevent="send"></textarea><div class="composer-bottom"><label class="icon"><AttachOutline/><input type="file" aria-label="添加附件" @change="upload"></label><button class="send" aria-label="发送问题" :disabled="loading||!question.trim()"><PaperPlaneOutline/></button></div></form><small class="demo-caption">演示内容 · 回答与引用仅用于体验交互</small></div>
    </template>
    <template v-else-if="page==='knowledge'">
      <header class="page-header"><div><button v-if="detail" class="back" @click="detail=false;query='' "><ArrowBackOutline/>知识库</button><h1>{{detail?library:'知识库'}}</h1><p>{{detail?'整理文件，让知识随时可用。':'把团队的资料，变成有依据的回答。'}}</p></div><label v-if="detail" class="primary"><AddOutline/>上传文件<input type="file" aria-label="上传文件" @change="upload"></label><button v-else class="primary" @click="startModal('knowledge')"><AddOutline/>新建知识库</button></header>
      <div class="page-body"><div class="search-field"><SearchOutline/><input v-model="query" :placeholder="detail?'搜索文件':'搜索知识库'" :aria-label="detail?'搜索文件':'搜索知识库'"></div>
      <div v-if="!detail" class="library-list"><button v-for="l in libraries.filter(l=>l.name.includes(query))" class="library-row" @click="library=l.name;detail=true;query='' "><div class="library-icon"><BookOutline/></div><div><h2>{{l.name}}</h2><p>{{l.desc}}</p></div><span>{{l.count}} 个文件</span><ChevronForwardOutline/></button></div>
      <template v-else><div class="tabs"><button class="selected">文件</button><button @click="drawer='kb-settings'">知识库设置</button></div><div class="table-wrap"><table><thead><tr><th>文件名称</th><th>大小</th><th>处理状态</th><th>操作</th></tr></thead><tbody><tr v-for="d in filteredDocs"><td><button class="file-button" @click="drawer='source'"><DocumentTextOutline/>{{d.name}}</button></td><td>{{d.size}}</td><td><span class="status" :class="{error:d.status==='处理失败',pending:d.status==='处理中'}"><component :is="d.status==='处理失败'?AlertCircleOutline:CheckmarkCircleOutline"/>{{d.status}}</span></td><td><button class="text-button" @click="d.status==='处理失败'?retry(d):drawer='source'">{{d.status==='处理失败'?'重试':'查看'}}</button></td></tr></tbody></table></div><p class="muted" v-if="!filteredDocs.length">没有找到匹配的文件</p><p class="table-note">上传完成后仍需解析与索引，显示“可检索”后才会用于回答。</p></template></div>
    </template>
    <template v-else-if="page==='agents'">
      <header class="page-header"><div><h1>智能体</h1><p>为不同的问题，配置合适的知识与能力。</p></div><button class="primary" @click="startModal('agent')"><AddOutline/>新建智能体</button></header><div class="page-body"><div class="search-field"><SearchOutline/><input v-model="query" placeholder="搜索智能体" aria-label="搜索智能体"></div><div class="agent-grid"><section v-for="a in agents.filter(a=>a.name.includes(query))" class="agent-card"><GridOutline/><h2>{{a.name}}</h2><p>{{a.desc}}</p><span class="chip"><BookOutline/>{{a.kb}}</span><div class="agent-actions"><button class="text-button" @click="assistant=a.name;newChat()">开始对话<ChevronForwardOutline/></button><button class="icon" aria-label="配置智能体" @click="assistant=a.name;drawer='agent-settings'"><SettingsOutline/></button></div></section></div></div>
    </template>
    <template v-else-if="page==='workflows'">
      <header class="page-header"><div><button v-if="editor" class="back" @click="editor=false"><ArrowBackOutline/>工作流</button><h1>{{editor?'知识问答流程':'工作流'}}</h1><p>{{editor?'将检索、模型与回答连接起来。':'让多步骤任务，按清晰的路径执行。'}}</p></div><div class="button-group"><button v-if="editor" class="secondary" @click="notify('演示流程已保存')"><SaveOutline/>保存</button><button class="primary" @click="editor?run():editor=true"><component :is="editor?PlayOutline:AddOutline"/>{{editor?(running?'运行中…':'测试运行'):'新建工作流'}}</button></div></header>
      <div v-if="!editor" class="page-body"><button class="library-row" @click="editor=true"><div class="library-icon"><GitNetworkOutline/></div><div><h2>知识问答流程</h2><p>检索知识库，生成有来源的回答</p></div><span class="chip">草稿</span><ChevronForwardOutline/></button></div>
      <div v-else class="workflow"><div class="flow-toolbar"><span>画布</span><button @click="drawer='nodes'"><AddOutline/>添加节点</button><span class="spacer"></span><small>点击节点配置</small></div><div class="flow-canvas"><div class="flow-track"><template v-for="(n,i) in ['开始','知识检索','大模型','回答']"><button class="flow-node" :class="{chosen:activeNode===n}" @click="activeNode=n;drawer='node'"><component :is="i===0?PlayOutline:i===1?BookOutline:i===2?GridOutline:ChatbubbleEllipsesOutline"/><b>{{n}}</b><small>{{['接收用户问题','从知识库查找资料','组织回答内容','返回答案与引用'][i]}}</small></button><ChevronForwardOutline v-if="i<3" class="connector"/></template></div></div><p class="canvas-note">交互演示：节点配置与测试结果均为模拟；正式版本保留现有画布能力。</p></div>
    </template>
    <template v-else>
      <header class="page-header"><div><h1>设置</h1><p>按你的使用方式，连接模型与工具。</p></div></header><div class="settings-layout"><nav class="settings-nav"><button v-for="s in settings" :class="{active:setting===s}" @click="setting=s">{{s}}</button><button @click="drawer='help'">帮助文档</button></nav><section class="settings-content"><h2>{{setting}}</h2><template v-if="setting==='外观'"><p class="muted">选择适合当前环境的主题。</p><div class="theme-options"><button :class="{chosen:!dark}" @click="dark=false;sync()"><SunnyOutline/>浅色</button><button :class="{chosen:dark}" @click="dark=true;sync()"><MoonOutline/>深色</button></div></template><template v-else><p class="muted">{{setting==='模型配置'?'管理用于对话、向量化和排序的模型。':'现有功能入口保留，统一表单与状态样式。'}}</p><form class="settings-form" @submit.prevent="notify('配置已保存到本次演示')"><label>配置名称<input :placeholder="setting==='模型配置'?'默认对话模型':setting+'配置'" required></label><label>服务地址<input placeholder="https://example.com/api" type="url" required></label><label v-if="setting==='模型配置'">模型用途<select><option>对话模型</option><option>向量模型</option><option>重排模型</option></select></label><div class="setting-note">演示不连接外部服务，请勿输入真实密钥。</div><div class="button-group"><button type="button" class="secondary" @click="notify('演示连接检查通过')">测试连接</button><button class="primary">保存配置</button></div></form></template></section></div>
    </template>
  </main>
  <footer class="copyright">本系统版权归 SparkX v2.0 所有</footer>
  <button v-if="isDev" class="prototype-badge" @click="drawer='prototype'">原型 A · {{page}} · {{dark?'深色':'浅色'}}</button>
  <div v-if="drawer" class="shade" @click.self="drawer='' "><section class="drawer" role="dialog" aria-modal="true" :aria-label="drawer==='source'?'引用来源':'详情面板'"><header><h2>{{({source:'引用来源',history:'全部对话','chat-settings':'对话设置','kb-settings':'知识库设置','agent-settings':'智能体配置',node:activeNode,nodes:'添加节点',run:'运行结果',help:'帮助与说明',prototype:'交互原型'})[drawer]}}</h2><button class="icon" aria-label="关闭面板" @click="drawer='' "><CloseOutline/></button></header>
  <template v-if="drawer==='source'"><div class="source-file"><DocumentTextOutline/><div><b>差旅管理办法.pdf</b><small>企业制度 · 第 3 页</small></div></div><h3>三、出差申请与审批</h3><p class="source-copy">员工出差前，应提交包含出差事由、目的地、出行时间与费用预算的申请。经审批通过后，再安排相关行程。</p><blockquote>请妥善保留审批记录，作为报销时的相关凭据。</blockquote><p class="muted">以上为原型示例文档，未读取你的真实资料。</p></template>
  <template v-else-if="drawer==='history'"><button v-for="h in histories" class="history-full" @click="openChat(h);drawer='' ">{{h}}<ChevronForwardOutline/></button></template>
  <template v-else-if="drawer==='run'"><p class="status"><CheckmarkCircleOutline/>演示运行完成</p><p>开始 → 知识检索 → 大模型 → 回答</p><div class="result-box">已找到相关资料，并生成带引用的回答。</div></template>
  <template v-else-if="drawer==='nodes'"><button v-for="n in ['智能体','知识检索','大模型','意图识别','条件分支','知识图谱','回答']" class="history-full" @click="activeNode=n;drawer='node'">{{n}}<AddOutline/></button></template>
  <template v-else-if="drawer==='prototype'"><p>基于已选视觉 A 的一次性交互原型。</p><p>所有数据仅保存在内存，刷新后重置。附件不会上传，连接检查与流程运行是模拟。</p><p>当前页面：{{page}}<br>主题：{{dark?'深色':'浅色'}}<br>智能体：{{assistant}}</p><button class="secondary" @click="theme">切换主题</button><p class="muted">旧版权通知按已确认的品牌边界保留。</p></template>
  <template v-else-if="drawer==='help'"><p>从左侧选择对话、知识库、智能体或工作流。点击回答下的来源，可核对文档片段。</p><a href="https://github.com/hhhrrr777/SparkX/blob/master/README.md" target="_blank" rel="noreferrer">打开项目文档</a></template>
  <form v-else class="settings-form" @submit.prevent="notify('设置已保存到本次演示');drawer='' "><label>名称<input :value="drawer==='node'?activeNode:assistant"></label><label>关联知识库<select v-model="selectedKnowledge"><option v-for="l in libraries">{{l.name}}</option></select></label><label>说明<textarea placeholder="补充说明…"></textarea></label><button class="primary">保存设置</button></form>
  </section></div>
  <div v-if="modal" class="shade" @click.self="modal='' "><form class="modal" role="dialog" aria-modal="true" aria-label="创建项目" @submit.prevent="saveModal"><header><h2>{{modal==='knowledge'?'新建知识库':'新建智能体'}}</h2><button type="button" class="icon" aria-label="关闭弹窗" @click="modal='' "><CloseOutline/></button></header><label>名称<input v-model="formName" placeholder="输入名称" required autofocus></label><label>描述<textarea v-model="formDesc" placeholder="简单介绍它的用途"></textarea></label><label v-if="modal==='agent'">知识库<select v-model="selectedKnowledge"><option v-for="l in libraries">{{l.name}}</option></select></label><div class="modal-actions"><button type="button" class="secondary" @click="modal='' ">取消</button><button class="primary">创建</button></div></form></div>
  <div v-if="toast" class="toast" role="status"><CheckmarkCircleOutline/>{{toast}}</div>
</div>
